contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Parameters:
    //   initMin: initial MinSum to set
    //   putAmount: ETH to send to Put to fund the holder
    //   collectAmount: amount to attempt to Collect
    function run(uint initMin, uint putAmount, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (putAmount)); require(putAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= putAmount);

        // Initialize c so Collect can potentially succeed
        c.SetMinSum(initMin); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(c)); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;

        // Fund this test contract's holder inside C
        c.Put{value: putAmount}(0); if (__ESBMC_reverted()) return;

        // Read stored holder record (unlockTime, balance) via public getter
        (uint unlockBefore, uint balBefore) = c.Acc(address(this)); if (__ESBMC_reverted()) return;

        // Attempt Collect and record whether it reverted
        bool reverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Read stored holder record after Collect
        (uint unlockAfter, uint balAfter) = c.Acc(address(this)); if (__ESBMC_reverted()) return;

        // Also observe the contract's on-chain ETH balance
        uint contractEth = address(c).balance;

        // General rule:
        // If Collect did not revert then (1) the Acc getter returns balAfter as the holder's stored balance,
        // and (2) the contract's ETH balance is >= that stored balance (contract must hold at least recorded sums).
        // We also assert that unlockTime is unchanged by Collect (Collect should not modify unlockTime) when it returns.
        assert(reverted || (balAfter == balAfter && contractEth >= balAfter && unlockBefore == unlockAfter));
    }

    receive() external payable {}
}

