// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 initMin, uint256 putAmount, uint256 collectAmount) internal {
        putAmount = bound(putAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= putAmount);
        try c.SetMinSum(initMin) {} catch { return; }
        try c.SetLogFile(address(c)) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Put{value: putAmount}(0) {} catch { return; }
        uint256 unlockBefore;
        uint256 balBefore;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockBefore = __r0; balBefore = __r1; } catch { return; }
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 unlockAfter;
        uint256 balAfter;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { unlockAfter = __r0; balAfter = __r1; } catch { return; }
        uint contractEth = address(c).balance;
        assertTrue(reverted || (balAfter == balAfter && contractEth >= balAfter && unlockBefore == unlockAfter));
    }

    function testFuzz_run(uint256 initMin, uint256 putAmount, uint256 collectAmount) public {
        _run(initMin, putAmount, collectAmount);
    }

    receive() external payable {}
}
